import { contextBridge } from "electron";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import process from "node:process";

// Expose a minimal, safe API to the renderer
let runtimeConfig = {};
try {
  // config.json will be placed next to the asar (copied from build step) or in resources directory
  const __filename = fileURLToPath(import.meta.url);
  const __dirname = path.dirname(__filename);
  const possible = [
    path.join(process.resourcesPath || "", "config.json"),
    path.join(__dirname, "..", "config.json"),
  ];
  for (const p of possible) {
    if (p && fs.existsSync(p)) {
      const raw = fs.readFileSync(p, "utf-8");
      runtimeConfig = JSON.parse(raw);
      break;
    }
  }
} catch {
  // swallow; fallback to empty config
}

// Optional: initialize Realm (Device Sync) if configured
let realmApi = null;
async function initRealmIfEnabled() {
  try {
    const mode = runtimeConfig?.dataMode || "rest";
    if (mode !== "realm") return null;
    const appId = runtimeConfig?.realm?.appId;
    if (!appId) return null;
    const Realm = (await import("realm")).default;
    const Credentials = Realm.Credentials;
    const { BSON } = Realm;
    const app = new Realm.App({ id: appId });
    // Auth
    const auth = runtimeConfig?.realm?.auth || { provider: "anonymous" };
    let user = null;
    if (auth.provider === "anonymous") {
      user = await app.logIn(Credentials.anonymous());
    } else if (
      auth.provider === "emailPassword" &&
      auth.email &&
      auth.password
    ) {
      user = await app.logIn(
        Credentials.emailPassword(auth.email, auth.password)
      );
    } else if (auth.provider === "apiKey" && auth.apiKey) {
      user = await app.logIn(Credentials.apiKey(auth.apiKey));
    } else {
      user = await app.logIn(Credentials.anonymous());
    }
    // Schemas (minimal subset to start)
    const SupplierSchema = {
      name: "Supplier",
      primaryKey: "_id",
      properties: {
        _id: "objectId",
        supplierName: "string",
        phoneNumber: "string?",
        address: "string?",
        createdAt: { type: "date", default: new Date() },
        updatedAt: { type: "date", default: new Date() },
      },
    };
    const MedicineSchema = {
      name: "Medicine",
      primaryKey: "_id",
      properties: {
        _id: "objectId",
        medicineName: "string",
        brand: "string?",
        category: "string?",
        unit: "string?",
        baseUnit: "string?",
        packUnit: "string?",
        packSize: "int?",
        batchNumber: "string",
        expiryDate: "date?",
        purchasePrice: "double?",
        sellingPrice: "double?",
        supplierId: "objectId?",
        isDeleted: { type: "bool", default: false },
        createdAt: { type: "date", default: new Date() },
        updatedAt: { type: "date", default: new Date() },
      },
    };
    const realm = await Realm.open({
      schema: [SupplierSchema, MedicineSchema],
      sync: {
        user,
        flexible: true,
        onError: (_s, e) => console.error("[Realm]", e),
      },
    });
    // Subscriptions
    await realm.subscriptions.update((subs) => {
      const filters = runtimeConfig?.realm?.subscriptions || {};
      try {
        subs.add(
          realm
            .objects("Medicine")
            .filtered(filters.medicines?.filter || "TRUEPREDICATE"),
          {
            name: "medicines",
            throwOnUpdate: false,
          }
        );
      } catch {
        // ignore duplicate subscription errors
      }
      try {
        subs.add(realm.objects("Supplier"), {
          name: "suppliers",
          throwOnUpdate: false,
        });
      } catch {
        // ignore duplicate subscription errors
      }
    });
    // CRUD helpers
    const toHex = (oid) =>
      oid && typeof oid.toHexString === "function" ? oid.toHexString() : oid;
    const api = {
      listMedicines() {
        return realm
          .objects("Medicine")
          .filtered("isDeleted == false")
          .map((x) => ({
            _id: toHex(x._id),
            medicineName: x.medicineName,
            brand: x.brand,
            category: x.category,
            unit: x.unit,
            baseUnit: x.baseUnit,
            packUnit: x.packUnit,
            packSize: x.packSize,
            batchNumber: x.batchNumber,
            expiryDate: x.expiryDate,
            purchasePrice: x.purchasePrice,
            sellingPrice: x.sellingPrice,
            supplierId: toHex(x.supplierId),
            isDeleted: x.isDeleted,
            createdAt: x.createdAt,
            updatedAt: x.updatedAt,
          }));
      },
      addMedicine(payload) {
        let id = new BSON.ObjectId();
        realm.write(() => {
          realm.create("Medicine", {
            _id: id,
            ...payload,
            createdAt: new Date(),
            updatedAt: new Date(),
            isDeleted: false,
          });
        });
        return id.toHexString();
      },
      softDeleteMedicine(idHex) {
        realm.write(() => {
          const id = new BSON.ObjectId(idHex);
          const obj = realm.objectForPrimaryKey("Medicine", id);
          if (obj) obj.isDeleted = true;
        });
      },
      listSuppliers() {
        return realm.objects("Supplier").map((x) => ({
          _id: toHex(x._id),
          supplierName: x.supplierName,
          phoneNumber: x.phoneNumber,
          address: x.address,
          createdAt: x.createdAt,
          updatedAt: x.updatedAt,
        }));
      },
      updateSupplier(idHex, patch) {
        realm.write(() => {
          const id = new BSON.ObjectId(idHex);
          const obj = realm.objectForPrimaryKey("Supplier", id);
          if (obj) {
            if (patch.supplierName != null)
              obj.supplierName = patch.supplierName;
            if (patch.phoneNumber != null) obj.phoneNumber = patch.phoneNumber;
            if (patch.address != null) obj.address = patch.address;
            obj.updatedAt = new Date();
          }
        });
      },
      addSupplier(payload) {
        let id = new BSON.ObjectId();
        realm.write(() => {
          realm.create("Supplier", {
            _id: id,
            ...payload,
            createdAt: new Date(),
            updatedAt: new Date(),
          });
        });
        return id.toHexString();
      },
      deleteSupplier(idHex) {
        realm.write(() => {
          const id = new BSON.ObjectId(idHex);
          const obj = realm.objectForPrimaryKey("Supplier", id);
          if (obj) realm.delete(obj);
        });
      },
      _raw: realm,
    };
    return api;
  } catch (e) {
    console.error("[Preload] Failed to init Realm:", e);
    return null;
  }
}

// Initialize realm in background. Exposure remains stable if null.
initRealmIfEnabled().then((api) => {
  realmApi = api;
});

contextBridge.exposeInMainWorld("desktop", {
  isElectron: true,
  config: runtimeConfig,
  getVersion: () =>
    process && process.versions ? process.versions.electron : undefined,
  emit: (channel, payload) => {
    window.dispatchEvent(
      new CustomEvent(`desktop:${channel}`, { detail: payload })
    );
  },
  // Realm-aware bridge (no-ops if not configured)
  realm: {
    ready: async () => Boolean(realmApi),
    listMedicines: async () => (realmApi ? realmApi.listMedicines() : []),
    addMedicine: async (payload) => realmApi?.addMedicine(payload),
    softDeleteMedicine: async (id) => realmApi?.softDeleteMedicine(id),
    listSuppliers: async () => (realmApi ? realmApi.listSuppliers() : []),
    addSupplier: async (payload) => realmApi?.addSupplier(payload),
    updateSupplier: async (id, patch) => realmApi?.updateSupplier(id, patch),
    deleteSupplier: async (id) => realmApi?.deleteSupplier(id),
  },
});
